most_repeated_storage_engine_query.text:
SET DC_KIND="DENSE";
SELECT
[Fiscal Year (10)].[Financial Year (248)] AS [Fiscal Year (10)$Financial Year (248)],
SUM([Allocation Bridge  derived  (127)].[Allocated Amount  stored  (617)]) AS [$Measure0], COUNT()
FROM [Allocation Bridge  derived  (127)]
	LEFT OUTER JOIN [Fiscal Year (10)] ON [Allocation Bridge  derived  (127)].[Fiscal Year Key (611)]=[Fiscal Year (10)].[Financial Year (248)];

